import{_ as e,o as r,c as s,a2 as t}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"索引管理","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/index-drives.md","filePath":"zh-CN/user-guide/settings/index-drives.md","lastUpdated":1787586465000}'),l={name:"zh-CN/user-guide/settings/index-drives.md"};function n(i,o,a,d,g,c){return r(),s("div",null,[...o[0]||(o[0]=[t('<h1 id="索引管理" tabindex="-1">索引管理 <a class="header-anchor" href="#索引管理" aria-label="Permalink to &quot;索引管理&quot;">​</a></h1><p>索引设置页面用于精细化控制 Lertaro 针对本地硬盘、网络存储、WSL 子系统以及自定义文件夹的索引范围、刷新策略与排除规则。页面顶部包含五个标签页：<strong>本地驱动器</strong>、<strong>网络驱动器</strong>、<strong>WSL</strong>（检测到发行版时自动显示）、<strong>文件夹</strong>与<strong>排除规则</strong>。</p><h2 id="_1-本地驱动器-local-drives" tabindex="-1">1. 本地驱动器（Local Drives） <a class="header-anchor" href="#_1-本地驱动器-local-drives" aria-label="Permalink to &quot;1. 本地驱动器（Local Drives）&quot;">​</a></h2><ul><li><strong>顶部汇总状态</strong>：展示当前已索引的物理驱动器数量与总文件/文件夹条目数，并提供<strong>重建索引</strong>按钮触发所有本地磁盘的全量重建。</li><li><strong>驱动器列表行</strong>：每个物理分区独立显示一行： <ul><li><strong>启用/禁用复选框</strong>：独立开关该磁盘的索引。</li><li><strong>文件系统与状态</strong>：显示底层文件系统类型（NTFS、ReFS、FAT32、exFAT 等）、当前状态与已索引条目数。</li><li><strong>单盘操作</strong>：每行提供独立的<strong>重建</strong>与<strong>移除</strong>操作；在重建扫描进行时会动态提供<strong>停止</strong>按钮。</li></ul></li><li><strong>实时监控机制</strong>：NTFS 与 ReFS 卷通过 Windows 系统的 USN 变更日志实现毫秒级增量同步；FAT32 与 exFAT 卷通过文件系统实时变更事件监听。</li><li><strong>无缝重建保障</strong>：在某个磁盘重建期间，旧索引将继续响应用户的搜索查询，直到新索引构建完成时瞬间无缝替换，搜索体验绝不中断。若重建过程被系统重启或手动停止中断，下次会自动从断点继续。</li></ul><h2 id="_2-网络驱动器-network-drives" tabindex="-1">2. 网络驱动器（Network Drives） <a class="header-anchor" href="#_2-网络驱动器-network-drives" aria-label="Permalink to &quot;2. 网络驱动器（Network Drives）&quot;">​</a></h2><ul><li><strong>网络存储支持</strong>：展示所有已映射的 Windows 网络共享磁盘（SMB / NAS）。</li><li><strong>刷新模式（Refresh Mode）</strong>：网络存储缺乏本地 USN 日志，因此支持定制计划轮询策略： <ul><li><strong>手动</strong> —— 仅在点击“重建索引”时重新扫描。</li><li><strong>每 15 分钟</strong> —— 高频协同办公目录推荐。</li><li><strong>每小时</strong> —— 均衡型定时扫描。</li><li><strong>每天</strong> —— 静态归档共享推荐。</li></ul></li><li><strong>符号链接环路保护</strong>：扫描引擎内置了分支祖先路径栈与符号链接循环检测算法，即使 NAS 共享中存在指向父级目录的软链接或重解析点，也能自动拦截死循环，确保索引数量准确不膨胀。</li></ul><h2 id="_3-wsl-linux-子系统" tabindex="-1">3. WSL（Linux 子系统） <a class="header-anchor" href="#_3-wsl-linux-子系统" aria-label="Permalink to &quot;3. WSL（Linux 子系统）&quot;">​</a></h2><p>当且仅当系统检测到至少安装了一个 WSL 发行版时，本标签页会自动出现：</p><ul><li><strong>自动探测</strong>：自动识别 Ubuntu、Debian、Arch 等已安装的 WSL 发行版。</li><li><strong>状态与刷新</strong>：提供与网络驱动器完全一致的状态监控与刷新模式配置（手动 / 每 15 分钟 / 每小时 / 每天）。</li><li><strong>零 I/O 搜索</strong>：搜索 WSL 文件时直接查询内存索引树，完全不唤醒或阻塞 Linux 子系统。</li></ul><h2 id="_4-文件夹-folders" tabindex="-1">4. 文件夹（Folders） <a class="header-anchor" href="#_4-文件夹-folders" aria-label="Permalink to &quot;4. 文件夹（Folders）&quot;">​</a></h2><p>当你不希望索引整个驱动器或整台 NAS 服务器，而只想精准收录特定工作目录时，可以使用自定义文件夹索引：</p><ul><li><strong>多选添加</strong>：点击<strong>添加文件夹</strong>按钮打开原生选择器，支持按住 <code>Ctrl</code> 或 <code>Shift</code> 一次性批量选择添加多个目录。</li><li><strong>UNC 路径支持</strong>：支持直接添加类似 <code>\\\\server\\share\\projects</code> 的局域网 UNC 共享目录。</li><li><strong>独立计划刷新</strong>：每个文件夹均拥有独立的启用开关、条目计数与刷新模式下拉框（手动 / 每 15 分钟 / 每小时 / 每天）。</li></ul><h2 id="_5-排除规则-exclusions" tabindex="-1">5. 排除规则（Exclusions） <a class="header-anchor" href="#_5-排除规则-exclusions" aria-label="Permalink to &quot;5. 排除规则（Exclusions）&quot;">​</a></h2><p>排除规则全局作用于本地磁盘、网络存储与自定义文件夹，分为三个子标签页：</p><h3 id="路径排除-path-exclusions" tabindex="-1">路径排除（Path Exclusions） <a class="header-anchor" href="#路径排除-path-exclusions" aria-label="Permalink to &quot;路径排除（Path Exclusions）&quot;">​</a></h3><ul><li><strong>匹配机制</strong>：按完整物理路径前缀进行精确屏蔽。</li><li><strong>环境变量支持</strong>：支持输入 <code>%ProgramData%</code>、<code>%APPDATA%</code> 或 <code>D:\\Cache</code>。</li></ul><h3 id="glob-通配符排除-glob-rules" tabindex="-1">Glob 通配符排除（Glob Rules） <a class="header-anchor" href="#glob-通配符排除-glob-rules" aria-label="Permalink to &quot;Glob 通配符排除（Glob Rules）&quot;">​</a></h3><ul><li><strong>常见语法</strong>： <ul><li><code>*</code>：匹配单层目录内的任意字符（如 <code>*.tmp</code>、<code>*.log</code>）。</li><li><code>**</code>：跨层级递归匹配任意子目录（如 <code>**/node_modules/**</code>、<code>**/bin/**</code>、<code>**/obj/**</code>）。</li></ul></li></ul><h3 id="正则表达式排除-regex-rules" tabindex="-1">正则表达式排除（Regex Rules） <a class="header-anchor" href="#正则表达式排除-regex-rules" aria-label="Permalink to &quot;正则表达式排除（Regex Rules）&quot;">​</a></h3><ul><li><strong>高级过滤</strong>：针对完整路径或文件名进行正则匹配。例如使用 <code>^\\.</code> 排除 Linux 式隐藏点文件，使用 <code>~\\$</code> 排除 Office 产生的临时锁定文件。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>排除规则支持<strong>单条添加</strong>与<strong>批量导入导出</strong>：点击<strong>从列表生成</strong>可将现有规则导出为多行文本，编辑后点击<strong>应用到列表</strong>即可一次性批量生效。修改排除规则后，相关驱动器与文件夹会自动重新应用过滤。</p></div>',21)])])}const x=e(l,[["render",n]]);export{h as __pageData,x as default};
